// Prepare Harvey prompt from evidence pack and snapshot
const input = $input.first().json;

const evidencePack = input.evidence_pack || {};
const snapshot = input.snapshot || {};
const skills = input.skills || [];
const prompt = input.prompt || '';

// Build structured prompt for Harvey
const systemPrompt = `Eres un abogado especializado en due diligence societaria en España.
Genera un informe estructurado basándote EXCLUSIVAMENTE en las fuentes proporcionadas.

REGLAS DE CITACIÓN:
- CITA cada afirmación factual usando [SRC-XXX]
- NO inventes fuentes
- Si no tienes evidencia para una afirmación, indica "Sin evidencia disponible"
- Todas las URLs deben ser de boe.es o borme.es

SECCIONES REQUERIDAS:
1. datos_generales - Información general de la sociedad
2. administradores - Órgano de administración actual
3. modificaciones - Cambios estatutarios relevantes
4. red_flags - Señales de alerta identificadas
5. conclusiones - Resumen ejecutivo para el equipo de DD`;

const userPrompt = `${prompt}\n\nEVIDENCE PACK:\n${JSON.stringify(evidencePack, null, 2)}\n\nSNAPSHOT:\n${JSON.stringify(snapshot, null, 2)}`;

return [{
  json: {
    report_id: input.report_id,
    request_id: input.request_id,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    evidence_pack: evidencePack,
    model: 'default'
  }
}];

// Format Harvey response for DD Legal PMO
const harveyResponse = $input.first().json;
const prevData = $('Prepare Harvey Prompt').first().json;

// Extract structured output
const output = {
  report_id: prevData.report_id,
  request_id: prevData.request_id,
  output: {
    raw_response: harveyResponse.text || harveyResponse.completion || JSON.stringify(harveyResponse),
    model_used: harveyResponse.model || 'harvey-default',
    generated_at: new Date().toISOString(),
    evidence_pack_version: '1.1',
    sections: {
      datos_generales: 'See raw_response',
      administradores: 'See raw_response',
      modificaciones: 'See raw_response',
      red_flags: 'See raw_response',
      conclusiones: 'See raw_response'
    }
  },
  status: 'ok'
};

return [{ json: output }];
